   262	    CHECK_F( BIT_initDStream(&bitD, cSrc, cSrcSize) );
   263	
   264	    HUF_decodeStreamX1(op, &bitD, oend, dt, dtLog);
   265	
   266	    if (!BIT_endOfDStream(&bitD)) return ERROR(corruption_detected);
